function releaseSettings(owner, repo, projectId, gitlab) {
  if (
    typeof owner !== "string" ||
    typeof repo !== "string" ||
    !/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(owner) ||
    !/^[A-Za-z0-9_.-]{1,100}$/.test(repo) ||
    [".", "..", "YOUR_GITHUB_REPOSITORY"].includes(repo)
  ) {
    throw new Error("Set the exact GitHub owner and repository.");
  }
  const id = Number(projectId);
  if (typeof projectId !== "string" || !/^[1-9]\d*$/.test(projectId) || !Number.isSafeInteger(id)) {
    throw new Error("Set the numeric ID of your target GitLab project.");
  }
  if (
    typeof gitlab !== "string" ||
    gitlab.length > 2048 ||
    !/^https:\/\/(?:(?:[A-Za-z0-9-]+\.)+[A-Za-z][A-Za-z0-9-]*|(?:\d{1,3}\.){3}\d{1,3})(?::\d{1,5})?(?:\/[A-Za-z0-9_-]+)*\/?$/.test(
      gitlab,
    ) ||
    /\/api(?:\/|$)/.test(gitlab)
  ) {
    throw new Error("Set the canonical HTTPS GitLab site URL without /api/v4.");
  }
  const site = gitlab.replace(/\/$/, "");
  const reservePrefix = [
    "gh-release",
    site,
    projectId,
    owner.toLowerCase(),
    repo.toLowerCase(),
    "",
  ].join(":");
  if (reservePrefix.length + 16 > 256) {
    throw new Error(
      "The combined GitHub and GitLab configuration is too long for the release reservation key.",
    );
  }
  return { owner, repo, projectId, id, gitlab: site, reservePrefix };
}

const { owner, repo, projectId, gitlab } = {
  owner: "YOUR_GITHUB_OWNER",
  repo: "YOUR_GITHUB_REPOSITORY",
  projectId: "YOUR_GITLAB_PROJECT_ID",
  gitlab: "https://gitlab.com",
};
return [{ json: releaseSettings(owner, repo, projectId, gitlab), pairedItem: { item: 0 } }];

function firstRelease(releases, cfg) {
  if (!Array.isArray(releases) || releases.length > 1)
    throw new Error("GitHub did not return a single newest release.");
  if (releases.length === 0) return { status: "no_release" };
  const release = releases[0];
  if (release?.draft === true) return { status: "draft_skipped" };
  const tag = release?.tag_name;
  const title = "Upstream release: " + tag;
  if (
    !Number.isSafeInteger(release?.id) ||
    release.id < 1 ||
    release.draft !== false ||
    typeof tag !== "string" ||
    !tag ||
    /[\s\p{Cc}]/u.test(tag) ||
    title.length > 255 ||
    (release.body !== null && typeof release.body !== "string") ||
    typeof release.html_url !== "string"
  ) {
    throw new Error("GitHub did not return a usable published release.");
  }
  const prefix = "https://github.com/" + cfg.owner + "/" + cfg.repo + "/releases/tag/";
  if (
    !release.html_url.toLowerCase().startsWith(prefix.toLowerCase()) ||
    decodeURIComponent(release.html_url.slice(prefix.length)) !== tag
  ) {
    throw new Error("GitHub returned a release for a different repository or tag.");
  }
  const url =
    "https://api.github.com/repos/" + cfg.owner + "/" + cfg.repo + "/releases/" + release.id;
  const notes = (release.body ?? "").replace(/\r\n?|[\u2028\u2029]/g, "\n").trimEnd();
  const description = notes
    ? url +
      "\n\n" +
      notes
        .split("\n")
        .map((line) => "    " + line)
        .join("\n")
    : url;
  if (description.length > 1_048_576)
    throw new Error("The release notes exceed the GitLab description limit.");
  return {
    status: "ready",
    tag,
    title,
    description,
    key: cfg.reservePrefix + release.id,
    releaseId: release.id,
  };
}

const config = $("Set the GitHub repository and GitLab project").itemMatching(0).json;
const release = firstRelease($input.first().json.body, config);
return [{ json: { release, config, ready: release.status === "ready" }, pairedItem: { item: 0 } }];

function verifyProject(project, cfg) {
  if (
    project?.id !== cfg.id ||
    project.archived !== false ||
    typeof project.web_url !== "string" ||
    typeof project.path_with_namespace !== "string" ||
    !/^[\w.-]+(?:\/[\w.-]+)+$/.test(project.path_with_namespace) ||
    project.web_url !== cfg.gitlab + "/" + project.path_with_namespace ||
    project.issues_enabled === false ||
    project.issues_access_level === "disabled"
  ) {
    throw new Error("GitLab did not confirm an active target project with issues enabled.");
  }
  return { ...cfg, projectUrl: project.web_url };
}

const { release, config } = $("Prepare the release and version").itemMatching(0).json;
return [
  {
    json: { release, config: verifyProject($input.first().json.body, config) },
    pairedItem: { item: 0 },
  },
];

const { release, config } = $("Verify the GitLab project").first().json;
const state =
  $runIndex === 0 ? { page: 1, seen: [], expectedTotal: null } : $input.first().json.state;
return [{ json: { release, config, state }, pairedItem: { item: 0 } }];

function includesVersion(title, version) {
  const prefix = "Upstream release: ";
  const generatedTag = title.startsWith(prefix) ? title.slice(prefix.length) : "";
  if (generatedTag && !/\s/u.test(generatedTag)) return generatedTag === version;
  const tagCharacter = (char) => Boolean(char && /[\p{L}\p{N}_+@\/\-]/u.test(char));
  let offset = title.indexOf(version);
  while (offset >= 0) {
    const left = title[offset - 1];
    const right = title[offset + version.length];
    const attachedBefore = tagCharacter(left) || (left === "." && tagCharacter(title[offset - 2]));
    const attachedAfter =
      tagCharacter(right) || (right === "." && tagCharacter(title[offset + version.length + 1]));
    if (!attachedBefore && !attachedAfter) return true;
    offset = title.indexOf(version, offset + 1);
  }
  return false;
}

function isIssueUrl(url, projectUrl, iid) {
  return url === projectUrl + "/-/issues/" + iid || url === projectUrl + "/issues/" + iid;
}

function scanIssuePage(issues, nextPage, total, cfg, release, state, pageSize) {
  const { page, seen, expectedTotal } = state;
  if (
    !Array.isArray(issues) ||
    issues.length > pageSize ||
    (nextPage !== null && nextPage !== page + 1) ||
    (total !== null &&
      (!Number.isSafeInteger(total) ||
        total < 0 ||
        (expectedTotal !== null && expectedTotal !== total)))
  ) {
    throw new Error("GitLab returned an invalid or changing issue page. No issue will be created.");
  }
  const ids = new Set(seen);
  let match = null;
  for (const issue of issues) {
    if (
      issue?.project_id !== cfg.id ||
      !Number.isSafeInteger(issue.iid) ||
      issue.iid < 1 ||
      typeof issue.title !== "string" ||
      !isIssueUrl(issue.web_url, cfg.projectUrl, issue.iid) ||
      ids.has(issue.iid)
    ) {
      throw new Error("GitLab returned a duplicate or an issue from a different project.");
    }
    ids.add(issue.iid);
    if (!match && includesVersion(issue.title, release.tag))
      match = { iid: issue.iid, url: issue.web_url };
  }
  if (match) return { status: "existing", match, more: false, state };
  const expected = expectedTotal ?? total;
  const more =
    nextPage !== null || (expected !== null ? ids.size < expected : issues.length === pageSize);
  if (
    (expected !== null && (ids.size > expected || (nextPage !== null && ids.size >= expected))) ||
    (more && (page >= 50 || issues.length === 0))
  ) {
    throw new Error("GitLab issues could not be scanned completely. No issue will be created.");
  }
  return {
    status: more ? "more" : "not_found",
    match: null,
    more,
    state: { page: page + 1, seen: [...ids], expectedTotal: expected },
  };
}

const { release, config, state } = $("Select the next issue page").itemMatching(0).json;
const { body, headers } = $input.first().json;
const numberHeader = (name) => {
  const value = headers[name];
  if (value === undefined || value === "") return null;
  if (typeof value !== "string" || !/^\d+$/.test(value))
    throw Error("GitLab returned invalid pagination headers.");
  return Number(value);
};
const result = scanIssuePage(
  body,
  numberHeader("x-next-page"),
  numberHeader("x-total"),
  config,
  release,
  state,
  100,
);
return [
  {
    json: { ...result, release, config, key: release.key, missing: result.status === "not_found" },
    pairedItem: { item: 0 },
  },
];

function isIssueUrl(url, projectUrl, iid) {
  return url === projectUrl + "/-/issues/" + iid || url === projectUrl + "/issues/" + iid;
}

function confirmReleaseIssue(issue, cfg, release) {
  if (
    issue?.project_id !== cfg.id ||
    !Number.isSafeInteger(issue.iid) ||
    issue.iid < 1 ||
    issue.title !== release.title ||
    issue.description !== release.description ||
    issue.state !== "opened" ||
    !isIssueUrl(issue.web_url, cfg.projectUrl, issue.iid)
  ) {
    throw new Error(
      "GitLab did not confirm the exact issue. Check the project before repeating the write.",
    );
  }
  return {
    status: "created",
    tag: release.tag,
    projectId: cfg.projectId,
    issueNumber: issue.iid,
    issueUrl: issue.web_url,
  };
}

const { config, release } = $("Look for the release version").itemMatching(0).json;
return [
  { json: confirmReleaseIssue($input.first().json.body, config, release), pairedItem: { item: 0 } },
];
